      const storageKey = 'team-site-theme';
      let saved = null;
      try { saved = localStorage.getItem(storageKey); } catch (_) { /* Storage may be unavailable. */ }
      const initial = saved === 'light' || saved === 'dark'
        ? saved
        : (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
      function applyTheme(theme, persist) {
        root.setAttribute('data-theme', theme);
        const dark = theme === 'dark';
        button.textContent = dark ? '☀' : '☾';
        const label = dark ? 'Switch to day mode' : 'Switch to night mode';
        button.setAttribute('aria-label', label);
        button.setAttribute('title', label);
        const meta = document.querySelector('meta[name="theme-color"]');
        if (meta) meta.setAttribute('content', dark ? '#14142B' : '#FFF8E7');
        if (persist) { try { localStorage.setItem(storageKey, theme); } catch (_) { /* Theme still works without storage. */ } }
      }
      applyTheme(initial, false);
      button.addEventListener('click', () => applyTheme(root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark', true));
    })();
  </script>
