    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; scroll-padding-top: 1.5rem; }
    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      font-size: 16px;
      line-height: 1.65;
      transition: background-color .2s ease, color .2s ease;
    }
    a { color: var(--accent); text-underline-offset: .2em; }
    a:hover { text-decoration-thickness: 2px; }
    :focus-visible { outline: 3px solid var(--accent); outline-offset: 4px; border-radius: 3px; }
    .wrap { width: min(100%, var(--max)); margin-inline: auto; padding-inline: clamp(1rem, 4vw, 3rem); }
    .site-header {
      min-height: 390px;
      position: relative;
      overflow: hidden;
      background: linear-gradient(135deg, var(--bg) 48%, var(--soft-accent));
      border-bottom: 1px solid var(--line);
    }
    .header-inner { padding-top: 1.25rem; padding-bottom: 4.5rem; }
    .topbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
    .wordmark { font-size: .8rem; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }
    .theme-toggle {
      width: 2.8rem; height: 2.8rem; display: grid; place-items: center;
      color: var(--text); background: var(--surface); border: 1px solid var(--line);
      border-radius: 50%; box-shadow: var(--shadow); font-size: 1.2rem; cursor: pointer;
    }
    .hero { max-width: 820px; padding-top: clamp(3rem, 8vw, 6rem); }
    .eyebrow { margin: 0 0 .7rem; color: var(--accent); font-size: .77rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
    h1, h2, h3, p { margin-top: 0; }
    h1 { max-width: 780px; margin-bottom: 1rem; font-size: clamp(2.7rem, 7vw, 5.8rem); line-height: .99; letter-spacing: -.065em; }
    .hero-copy { max-width: 640px; margin-bottom: 1.5rem; color: var(--muted); font-size: clamp(1.05rem, 2vw, 1.2rem); }
    .nav-links { display: flex; flex-wrap: wrap; gap: .6rem 1.4rem; margin-top: 1.3rem; }
    .nav-links a { font-size: .9rem; font-weight: 700; }
    main { padding-top: clamp(3.5rem, 7vw, 6rem); }
    section { scroll-margin-top: 1rem; }
    .section-heading { display: flex; align-items: end; justify-content: space-between; gap: 2rem; margin-bottom: 2rem; }
    .section-heading h2, .future h2 { margin: 0; font-size: clamp(2rem, 4vw, 3.3rem); line-height: 1.08; letter-spacing: -.045em; }
    .section-intro { max-width: 440px; margin: 0; color: var(--muted); }
    .member-grid { display: grid; grid-template-columns: 1fr; gap: 1.2rem; align-items: stretch; }
    .member-card {
      min-width: 0; padding: clamp(1.25rem, 2.3vw, 1.8rem); display: flex; flex-direction: column; align-items: flex-start;
      background: var(--surface); border-radius: 1rem; box-shadow: var(--shadow);
    }
    html[data-theme="dark"] .member-card { border: 1px solid var(--line); }
    .member-card img { width: 8rem; height: 8rem; max-width: 100%; margin-bottom: 1.2rem; border-radius: 50%; object-fit: cover; background: var(--soft-accent); }
    .member-card h3 { margin-bottom: .25rem; font-size: 1.55rem; letter-spacing: -.035em; }
    .study { min-height: 3.25em; margin-bottom: 1rem; color: var(--muted); font-size: .9rem; font-weight: 650; line-height: 1.5; }
    .bio { margin-bottom: .75rem; }
    .fun-fact { margin: 0 0 1rem; color: var(--muted); }
    .outlook { padding-top: .85rem; margin: 0 0 1.2rem; border-top: 1px solid var(--line); font-size: .95rem; }
    .outlook strong { color: var(--accent); }
    .hot-take { width: 100%; padding: .8rem .95rem; margin: auto 0 0; background: var(--accent); color: #fff; border-radius: .65rem; font-size: .93rem; font-weight: 750; line-height: 1.5; }
    .future { padding-block: clamp(4rem, 8vw, 7rem); }
    .future-panel { position: relative; overflow: hidden; padding: clamp(1.5rem, 5vw, 4rem); background: var(--surface); border-radius: 1.2rem; box-shadow: var(--shadow); }
    html[data-theme="dark"] .future-panel { border: 1px solid var(--line); }
    .future-panel::after { content: ""; position: absolute; right: -4rem; top: -5rem; width: 15rem; height: 15rem; border: 1px solid var(--line); border-radius: 50%; box-shadow: 0 0 0 2rem var(--bg), 0 0 0 2.06rem var(--line), 0 0 0 4rem var(--bg), 0 0 0 4.06rem var(--line); pointer-events: none; }
    .future h2 { position: relative; z-index: 1; max-width: 700px; margin-bottom: 1.5rem; }
    .future-copy { position: relative; z-index: 1; max-width: 790px; color: var(--muted); font-size: 1.08rem; }
    .future-copy p:last-child { margin-bottom: 0; }
    .principles { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr; gap: 1rem; margin-top: 2rem; }
    .principle { padding-top: .8rem; border-top: 2px solid var(--accent); }
    .principle h3 { margin-bottom: .3rem; font-size: 1rem; }
    .principle p { margin: 0; color: var(--muted); font-size: .94rem; }
    footer { padding-block: 1.6rem; border-top: 1px solid var(--line); color: var(--muted); text-align: center; }
    footer p { margin: .2rem 0; }
    @media (min-width: 760px) {
      .member-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.4rem; }
      .principles { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.5rem; }
    }
    @media (min-width: 1100px) { .member-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; } }
    @media (max-width: 759px) {
      .site-header { min-height: auto; }
      .header-inner { padding-bottom: 3rem; }
      .section-heading { align-items: flex-start; flex-direction: column; gap: .7rem; }
      .future-panel::after { opacity: .45; }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
    }
